# Confirm every currency-like numeric value has no more than two decimal places.
def is_currency_key(k):
    return k.endswith('_usd') or k in {'price_per_1000_tablets_usd','vial_price_usd','reimbursement_per_fill_300_patients_usd'}
def check(obj, path=''):
    if isinstance(obj, dict):
        for k,v in obj.items():
            if is_currency_key(k):
                assert isinstance(v,(int,float)), (path,k,v)
                assert round(v,2)==v, (path,k,v)
            check(v, f'{path}.{k}' if path else k)
    elif isinstance(obj, list):
        for i,v in enumerate(obj): check(v, f'{path}[{i}]')
